<script setup>
import {computed,ref} from 'vue';import {simulateQueue} from '../sim/models/queue.mjs';
const arrival=ref(800),workerRate=ref(400),workers=ref(1),asyncMode=ref(false);const r=computed(()=>simulateQueue({arrivalRate:arrival.value,workerRate:workerRate.value,workers:workers.value,async:asyncMode.value,seconds:10}));
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>工作進來：{{arrival}} /s</span><input v-model.number="arrival" type="range" min="100" max="2000" step="100"></div><div><span>Worker</span><div class="sim-segment"><button v-for="n in [1,2,4]" :key="n" :aria-pressed="workers===n" @click="workers=n">{{n}} 個</button></div><small>每個 worker 約 {{workerRate}} 件/s</small></div><div><span>通知是否留在 request path</span><div class="sim-segment"><button :aria-pressed="!asyncMode" @click="asyncMode=false">同步等待</button><button :aria-pressed="asyncMode" @click="asyncMode=true">非同步排隊</button></div></div></div><div class="sim-system"><div class="sim-node"><b>Order API</b><span>{{arrival}} req/s</span></div><div class="sim-arrow">→</div><div :class="['sim-node',{'is-warning':r.queueDepth>0,'is-critical':r.queueDepth>5000}]"><b>{{asyncMode?'Queue':'Notification call'}}</b><span>{{asyncMode?r.queueDepth+' 件等待':'request 等待結果'}}</span></div><div class="sim-arrow">→</div><div :class="['sim-node',{'is-critical':r.overloaded}]"><b>Worker / Provider</b><span>capacity {{r.capacity}} /s</span></div></div><div class="sim-metrics"><div><span>使用者等回覆</span><strong>{{r.requestLatency}} ms</strong></div><div><span>工作真正完成</span><strong>{{r.completionLatency}} ms</strong></div><div :class="{'is-bad':r.queueDepth>0}"><span>10 秒後 backlog</span><strong>{{r.queueDepth}}</strong></div><div><span>處理能力</span><strong>{{r.processedPerSec}} /s</strong></div></div><div :class="['sim-consequence',{'is-bad':r.overloaded}]"><strong>{{r.overloaded?'工作進來比做完更快':'目前 capacity 足夠'}}</strong><p v-if="asyncMode">非同步讓 request 可以先回覆，但工作完成時間沒有憑空消失。當 arrival 長期高於 capacity，queue 只會把等待累積起來。</p><p v-else>同步模式把 provider 的處理時間留在使用者等待路徑上。切成非同步，再比較「回覆快」和「工作完成快」是不是同一件事。</p></div></section></template>